<script lang="ts">
  import { onMount } from 'svelte'; import { api } from '$lib/api';
  type Branch = { id: string; name: string; archivedAt?: string | null }; let branches: Branch[] = [], branchId = '', providerName = '', circuitLabel = '', serviceType = 'fiber', statusValue = 'planned', downloadMbps = '', uploadMbps = '', addressingMode = 'unknown', review = false, message = '', error = '', loading = true;
  async function load() { loading = true; error = ''; try { const result = await api.get<{ items?: Branch[] } | Branch[]>('/api/branches'); branches = (Array.isArray(result) ? result : result.items ?? []).filter((branch) => !branch.archivedAt); } catch (e) { error = (e as Error).message; } finally { loading = false; } } onMount(load);
  const payload = () => ({ branch: branches.find((item) => item.id === branchId)?.name ?? branchId, providerName, circuitLabel, serviceType, status: statusValue, downloadMbps, uploadMbps, addressingMode });
  async function save() { error = ''; try { await api.post('/api/isp-circuits', { branchId, providerName, circuitLabel, serviceType, status: statusValue, downloadMbps: Number(downloadMbps), uploadMbps: Number(uploadMbps), addressingMode }, { headers: { 'Idempotency-Key': crypto.randomUUID() } }); message = 'ISP circuit saved.'; review = false; } catch (e) { error = (e as Error).message; } }
</script>
<svelte:head><title>ISP circuit intake</title></svelte:head><div class="page"><h1>ISP circuit intake</h1><p>Dynamic addressing is operational metadata, not permanent public-IP truth. Static address history, equipment assignments, and secret-reference links retain lifecycle history and use CAS/idempotency checks.</p>{#if loading}<section class="panel" role="status">Loading authorized branches…</section>{:else if error && !review}<section class="panel" role="alert"><p class="error">{error}</p><button onclick={load}>Retry</button></section>{:else if review}<section class="panel"><h2>Review before saving</h2><dl>{#each Object.entries(payload()) as [key, value]}<div><dt>{key}</dt><dd>{value || '—'}</dd></div>{/each}</dl><p>Cross-branch equipment requires a Super Admin-approved shared-service circuit policy. Sensitive address and secret-reference operations remain restricted.</p><button onclick={save} disabled={!branchId}>Confirm and save</button><button class="secondary" onclick={() => review = false}>Back to edit</button></section>{:else}<section class="panel">{#if branches.length === 0}<p>No active authorized branches are available.</p>{:else}<label for="branch">Branch</label><select id="branch" bind:value={branchId}><option value="">Select an authorized branch</option>{#each branches as branch}<option value={branch.id}>{branch.name}</option>{/each}</select><label for="provider">Provider</label><input id="provider" bind:value={providerName}/><label for="circuit">Circuit label</label><input id="circuit" bind:value={circuitLabel}/><label for="service">Service type</label><select id="service" bind:value={serviceType}><option>fiber</option><option>dsl</option><option>cable</option><option>wireless</option><option>leased_line</option><option>satellite</option><option>other</option></select><label for="status">Status</label><select id="status" bind:value={statusValue}><option>planned</option><option>active</option><option>degraded</option><option>suspended</option><option>terminated</option></select><label for="down">Download Mbps</label><input id="down" type="number" min="1" bind:value={downloadMbps}/><label for="up">Upload Mbps</label><input id="up" type="number" min="1" bind:value={uploadMbps}/><label for="addressing">Addressing mode</label><select id="addressing" bind:value={addressingMode}><option>static</option><option>dhcp</option><option>dynamic</option><option>pppoe</option><option>cgnat</option><option>unknown</option></select><button onclick={() => review = true} disabled={!branchId}>Review ISP circuit</button>{/if}</section>{/if}{#if error && review}<p role="alert" class="error">{error}</p>{/if}{#if message}<p role="status" class="ok">{message}</p>{/if}</div><style>.page{max-width:700px;margin:0 auto;padding:32px}.panel{border:1px solid #ddd;border-radius:10px;padding:20px}label{display:block;margin:12px 0 5px;font-weight:600}input,select{display:block;width:100%;padding:8px}.error{color:#b91c1c}.ok{color:#166534}button{margin-top:18px;padding:10px 14px}.secondary{margin-left:8px}</style>
